package tui
import("net/http";"strings";"testing";"time";"apitool/internal/app";"apitool/internal/model";"apitool/internal/runtime")
func TestHTTP401RendersResponseNotFailure(t *testing.T){m,_:=requestScreen(t,"GET",false);next,_:=m.Update(sendFinishedMsg{result:app.SendResult{Response:&model.Response{StatusCode:401}}});if !strings.Contains(next.View(),"401 Unauthorized")||strings.Contains(next.View(),"Request failed"){t.Fatal(next.View())}}
func TestResponseViewsAndDiagnostics(t *testing.T){
 for _,code:=range []int{302,401,500}{m,_:=requestScreen(t,"GET",false);m.width,m.height=110,32;next,_:=m.Update(sendFinishedMsg{result:app.SendResult{Response:&model.Response{StatusCode:code,Duration:time.Millisecond,Headers:http.Header{"Set-Cookie":{"secret"},"Content-Type":{"application/json"}},Body:[]byte(`{"ok":true}`)}}});view:=next.View();for _,want:=range []string{http.StatusText(code),"1ms","11 bytes","Content-Type","[REDACTED]","\"ok\": true"}{if !strings.Contains(view,want){t.Fatalf("missing %s: %s",want,view)}};if strings.Contains(view,"secret"){t.Fatal(view)}}
 for _,x:=range []*model.ExecutionError{{Stage:model.StageOAuth,Category:model.CategoryOAuth,SafeMessage:"OAuth failed"},{Stage:model.StageTransport,Category:model.CategoryDNS,SafeMessage:"DNS failed"}} {m,_:=requestScreen(t,"GET",false);next,_:=m.Update(sendFinishedMsg{result:app.SendResult{ExecutionError:x,Logs:[]runtime.LogEntry{{Method:"GET",Data:map[string]any{"access_token":"secret"}}}}});view:=next.View();for _,want:=range []string{string(x.Stage),string(x.Category),x.SafeMessage,"Request Log"}{if !strings.Contains(view,want){t.Fatalf("missing %s: %s",want,view)}};if strings.Contains(view,"secret"){t.Fatal(view)}}
}
func TestPrettyBodyFallsBackToRaw(t *testing.T){if got:=prettyBody([]byte("not json"));got!="not json"{t.Fatal(got)};if got:=prettyBody([]byte(`{"x":1}`));got!="{\n  \"x\": 1\n}"{t.Fatal(got)}}
